{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "summary_text",
        "sales_card",
        "view_report_button"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Q1 2024 Sales Overview",
        "variant": "h1"
      },
      "children": []
    },
    "summary_text": {
      "type": "Text",
      "props": {
        "text": "A comprehensive overview of sales performance for the first quarter of 2024, highlighting key trends and achievements."
      },
      "children": []
    },
    "sales_card": {
      "type": "Card",
      "props": {},
      "children": [
        "monthly_sales_h2",
        "sales_chart_title",
        "sales_table"
      ]
    },
    "monthly_sales_h2": {
      "type": "Text",
      "props": {
        "text": "Monthly Sales Performance",
        "variant": "h2"
      },
      "children": []
    },
    "sales_chart_title": {
      "type": "Text",
      "props": {
        "text": "Q1 2024 Monthly Sales",
        "variant": "h3"
      },
      "children": []
    },
    "sales_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "month",
            "label": "Month"
          },
          {
            "key": "sales",
            "label": "Sales ($)"
          }
        ],
        "rows": [
          {
            "month": "January",
            "sales": 15000
          },
          {
            "month": "February",
            "sales": 18000
          },
          {
            "month": "March",
            "sales": 22000
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": [
          "sales"
        ]
      },
      "children": []
    },
    "view_report_button": {
      "type": "Button",
      "props": {
        "label": "View Full Report",
        "variant": "primary"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/q1_2024_sales_report"
          }
        }
      },
      "children": []
    }
  }
}
